css:
.loader { --accent: var(--loader-color); --accent-2: var(--loader-secondary-color); width: var(--loader-size); height: var(--loader-size); position: relative; }
.loader span { position: absolute; left: 50%; top: 12%; width: calc(var(--loader-size) * .05); height: 76%; margin-left: calc(var(--loader-size) * -.025); background: var(--accent); border-radius: calc(var(--loader-size) * .05); transform-origin: 50% 100%; animation: swing calc(var(--loader-speed) * 1.6) ease-in-out infinite; }
.loader span::after { content: ''; position: absolute; top: -8%; left: 50%; width: calc(var(--loader-size) * .24); height: calc(var(--loader-size) * .24); margin-left: calc(var(--loader-size) * -.12); border-radius: 50%; background: var(--accent-2); }
@keyframes swing { 0%, 100% { transform: rotate(38deg); } 50% { transform: rotate(-38deg); } }
